import os
import smtplib
from email.message import EmailMessage

def main():
    # Retrieve secrets injected via GitHub Actions environment variables
    server = os.environ.get("MAIL_SERVER")
    port = int(os.environ.get("MAIL_PORT", 465))
    username = os.environ.get("MAIL_USERNAME")
    password = os.environ.get("MAIL_PASSWORD")
    recipient = os.environ.get("MAIL_RECIPIENT")

    # Read the summary text generated by diff_summary.py
    with open("email_body.txt", "r", encoding="utf-8") as f:
        body = f.read()

    # Construct the email message
    msg = EmailMessage()
    msg["Subject"] = "📅 HarpCal Update: Changes Detected for Harpenden Calendar"
    msg["From"] = f"HarpCal Bot <{username}>"
    msg["To"] = recipient
    msg.set_content(body)

    # Establish an encrypted connection directly to your mail server
    with smtplib.SMTP_SSL(server, port) as smtp:
        smtp.login(username, password)
        smtp.send_message(msg)

    print(f"Email notification successfully sent to {recipient}")

if __name__ == "__main__":
    main()
